#include <vector>
#include <algorithm>

class Solution {
public:
    int minXorSum(std::vector<int>& nums, int k) {
        int n = nums.size();
        std::vector<int> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] ^ nums[i];

        auto range_xor = [&](int i, int j) {
            return pref[j + 1] ^ pref[i];
        };

        std::vector<std::vector<int>> dp(n + 1, std::vector<int>(k + 1, 1e9));
        dp[0][0] = 0;

        for (int p = 1; p <= k; ++p) {
            for (int i = p; i <= n; ++i) {
                int best = 1e9;
                for (int j = p - 1; j < i; ++j) {
                    int cost = std::max(dp[j][p - 1], range_xor(j, i - 1));
                    if (cost < best) best = cost;
                }
                dp[i][p] = best;
            }
        }

        return dp[n][k];
    }
};

import java.util.*;

class Solution {
    public int minXorSum(int[] nums, int k) {
        int n = nums.length;
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] ^ nums[i];

        int[][] dp = new int[n + 1][k + 1];
        for (int i = 0; i <= n; i++) Arrays.fill(dp[i], 1000000000);
        dp[0][0] = 0;

        for (int p = 1; p <= k; p++) {
            for (int i = p; i <= n; i++) {
                int best = 1000000000;
                for (int j = p - 1; j < i; j++) {
                    int cost = Math.max(dp[j][p - 1], pref[i] ^ pref[j]);
                    if (cost < best) best = cost;
                }
                dp[i][p] = best;
            }
        }

        return dp[n][k];
    }
}

