var minXorSum = function(nums, k) {
    const n = nums.length;
    const pref = new Int32Array(n + 1);
    for (let i = 0; i < n; i++) pref[i + 1] = pref[i] ^ nums[i];

    const dp = Array.from({ length: n + 1 }, () => new Int32Array(k + 1).fill(1e9));
    dp[0][0] = 0;

    for (let p = 1; p <= k; p++) {
        for (let i = p; i <= n; i++) {
            let best = 1e9;
            for (let j = p - 1; j < i; j++) {
                const cost = Math.max(dp[j][p - 1], pref[i] ^ pref[j]);
                if (cost < best) best = cost;
            }
            dp[i][p] = best;
        }
    }

    return dp[n][k];
};
